=== seat.ts ===
import { Component, computed, ElementRef, inject, input, output } from '@angular/core';

import { SeatStatus } from '../../../core/models/seat-map.model';

@Component({
  selector: 'app-seat',
  imports: [],
  templateUrl: './seat.html',
  styleUrl: './seat.scss'
})
export class Seat {
  private readonly hostRef = inject(ElementRef<HTMLElement>);

  readonly row = input.required<string>();
  readonly column = input.required<number>();
  readonly status = input.required<SeatStatus>();
  readonly selected = input<boolean>(false);
  readonly focused = input<boolean>(false);

  readonly toggled = output<void>();

  protected readonly ariaLabel = computed(() => {
    const state = this.selected() ? 'ausgewählt' : this.status() === 'Free' ? 'frei' : 'belegt';
    return `Reihe ${this.row()}, Platz ${this.column()}, ${state}`;
  });

  protected onActivate(): void {
    if (this.status() === 'Occupied') {
      return;
    }
    this.focusSeat();
    this.toggled.emit();
  }

  protected onSpace(event: Event): void {
    event.preventDefault();
    this.onActivate();
  }

  public focusSeat(): void {
    (this.hostRef.nativeElement.querySelector('.seat') as HTMLElement | null)?.focus();
  }
}
=== seat.html ===
<div
  class="seat"
  [class.seat--free]="status() === 'Free' && !selected()"
  [class.seat--selected]="selected()"
  [class.seat--occupied]="status() === 'Occupied'"
  [attr.aria-label]="ariaLabel()"
  [attr.aria-disabled]="status() === 'Occupied' ? true : null"
  [attr.role]="status() === 'Occupied' ? null : 'button'"
  [attr.aria-pressed]="status() === 'Occupied' ? null : selected()"
  [attr.tabindex]="status() === 'Occupied' ? null : (focused() ? 0 : -1)"
  (click)="onActivate()"
  (keydown.enter)="onActivate()"
  (keydown.space)="onSpace($event)"
>
  @if (selected()) {
    <span class="seat__check" aria-hidden="true">✓</span>
  } @else if (status() === 'Free') {
    <span class="seat__symbol" aria-hidden="true">🪑</span>
  } @else {
    <span class="seat__cross" aria-hidden="true">×</span>
  }
</div>
